import java.util.Scanner;

public class Main {
    public static long gcdLL(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int n = sc.nextInt();

        int bestNum = 0;
        int bestDen = 1;
        double minDiff = Double.POSITIVE_INFINITY;

        for (int j = 1; j <= n; ++j) {
            int startI = (j * a) / b - 1;
            int endI = (j * a) / b + 1;
            for (int i = startI; i <= endI; ++i) {
                double currentDiff = Math.abs((double) i / j - (double) a / b);
                if (currentDiff < minDiff) {
                    minDiff = currentDiff;
                    bestNum = i;
                    bestDen = j;
                }
            }
        }
        long g = gcdLL(Math.abs((long) bestNum), bestDen);
        System.out.println((bestNum / g) + "/" + (bestDen / g));
        sc.close();
    }
}
